export const SPRITE_CALLBACKS = {
  "SpriteCB_Bicycle": "sprite->invisible = gSprites[sprite->sPlayerSpriteId].invisible;\n    sprite->x = gSprites[sprite->sPlayerSpriteId].x;\n    sprite->y = gSprites[sprite->sPlayerSpriteId].y + 8;\n    sprite->x2 = gSprites[sprite->sPlayerSpriteId].x2;\n    sprite->y2 = gSprites[sprite->sPlayerSpriteId].y2;",
  "SpriteCB_CreditsMon": "if (gIntroCredits_MovingSceneryState != INTROCRED_SCENERY_NORMAL)\n    {\n        FreeAndDestroyMonPicSprite(sprite->sSpriteId);\n        return;\n    }\n\n    sprite->data[7]++;\n    switch (sprite->sState)\n    {\n    case 0:\n    default:\n        sprite->oam.affineMode = ST_OAM_AFFINE_NORMAL;\n        sprite->oam.matrixNum = sprite->sPosition;\n        sprite->data[2] = 16;\n        SetOamMatrix(sprite->sPosition, 0x10000 / sprite->data[2], 0, 0, 0x10000 / sprite->data[2]);\n        sprite->invisible = FALSE;\n        sprite->sState = 1;\n        break;\n    case 1:\n        if (sprite->data[2] < 256)\n        {\n            sprite->data[2] += 8;\n            SetOamMatrix(sprite->sPosition, 0x10000 / sprite->data[2], 0, 0, 0x10000 / sprite->data[2]);\n        }\n        else\n        {\n            sprite->sState++;\n        }\n        switch (sprite->sPosition)\n        {\n        case POS_LEFT + 1:\n            if ((sprite->data[7] & 3) == 0)\n                sprite->y++;\n            sprite->x -= 2;\n            break;\n        case POS_CENTER + 1:\n            break;\n        case POS_RIGHT + 1:\n            if ((sprite->data[7] & 3) == 0)\n                sprite->y++;\n            sprite->x += 2;\n            break;\n        }\n        break;\n    case 2:\n        if (sprite->data[3] != 0)\n        {\n            sprite->data[3]--;\n        }\n        else\n        {\n            SetGpuReg(REG_OFFSET_BLDCNT, BLDCNT_EFFECT_BLEND | BLDCNT_TGT2_BG0 | BLDCNT_TGT2_BG1 | BLDCNT_TGT2_BG2 | BLDCNT_TGT2_BG3);\n            SetGpuReg(REG_OFFSET_BLDALPHA, BLDALPHA_BLEND(16, 0));\n            sprite->oam.objMode = ST_OAM_OBJ_BLEND;\n            sprite->data[3] = 16;\n            sprite->sState++;\n        }\n        break;\n    case 3:\n        if (sprite->data[3] != 0)\n        {\n            int data3;\n\n            sprite->data[3]--;\n\n            data3 = 16 - sprite->data[3];\n            SetGpuReg(REG_OFFSET_BLDALPHA, (data3 << 8) + sprite->data[3]);\n        }\n        else\n        {\n            sprite->invisible = TRUE;\n            sprite->sState = 9;\n        }\n        break;\n    case 9:\n        sprite->sState++;\n        break;\n    case 10:\n        SetGpuReg(REG_OFFSET_BLDCNT, 0);\n        SetGpuReg(REG_OFFSET_BLDALPHA, 0);\n        FreeAndDestroyMonPicSprite(sprite->data[6]);\n        break;\n    }",
  "SpriteCB_CreditsMonBg": "if (gSprites[sprite->sMonSpriteId].data[0] == 10\n     || gIntroCredits_MovingSceneryState != INTROCRED_SCENERY_NORMAL)\n    {\n        DestroySprite(sprite);\n        return;\n    }\n\n     \n    sprite->invisible = gSprites[sprite->sMonSpriteId].invisible;\n    sprite->oam.objMode = gSprites[sprite->sMonSpriteId].oam.objMode;\n    sprite->oam.affineMode = gSprites[sprite->sMonSpriteId].oam.affineMode;\n    sprite->oam.matrixNum = gSprites[sprite->sMonSpriteId].oam.matrixNum;\n    sprite->x = gSprites[sprite->sMonSpriteId].x;\n    sprite->y = gSprites[sprite->sMonSpriteId].y;",
  "SpriteCB_Cursor": "if (sprite->animEnded)\n        StartSpriteAnim(sprite, 0);\n\n     \n    sprite->invisible = sprite->sInvisible;\n    if (sprite->sX == GetCurrentPageColumnCount())\n        sprite->invisible = TRUE;\n\n    if (sprite->invisible\n       || !(sprite->sFlashing)\n       || sprite->sX != sprite->sPrevX\n       || sprite->sY != sprite->sPrevY)\n    {\n        sprite->sColor = 0;\n        sprite->sColorIncr = 2;\n        sprite->sColorDelay = 2;\n    }\n\n    sprite->sColorDelay--;\n    if (sprite->sColorDelay == 0)\n    {\n        sprite->sColor += sprite->sColorIncr;\n        if (sprite->sColor == 16 || sprite->sColor == 0)\n            sprite->sColorIncr = -sprite->sColorIncr;\n        sprite->sColorDelay = 2;\n    }\n\n    if (sprite->sFlashing)\n    {\n        s8 gb = sprite->sColor;\n        s8 r = sprite->sColor >> 1;\n        u16 index = OBJ_PLTT_ID(IndexOfSpritePaletteTag(PALTAG_CURSOR)) + 1;\n\n        MultiplyInvertedPaletteRGBComponents(index, r, gb, gb);\n    }",
  "SpriteCB_Flygon": "switch (sprite->sState)\n    {\n    case 0:\n        break;\n    case 1:\n        if (sprite->x2 + sprite->x < DISPLAY_WIDTH + 64)\n            sprite->x2 += 8;\n        else\n            sprite->sState = 2;\n        break;\n    case 2:\n        if (sprite->x2 + sprite->x > 120)\n            sprite->x2 -= 1;\n        else\n            sprite->sState = 3;\n        break;\n    case 3:\n        if (sprite->x2 > 0)\n            sprite->x2 -= 2;\n        break;\n    }\n    sprite->y2 = Sin((u8)sprite->sSinIdx, 8) - sFlygonYOffset;\n    sprite->sSinIdx += 4;",
  "SpriteCB_FlygonLeftHalf": "",
  "SpriteCB_FlygonRightHalf": "sprite->invisible = gSprites[sprite->sLeftSpriteId].invisible;\n    sprite->y = gSprites[sprite->sLeftSpriteId].y;\n    sprite->x2 = gSprites[sprite->sLeftSpriteId].x2;\n    sprite->y2 = gSprites[sprite->sLeftSpriteId].y2;",
  "SpriteCB_FlygonSilhouette": "sprite->sTimer++;\n\n    if (sprite->sState != 0)\n    {\n        s16 sin;\n        s16 cos;\n\n        s16 a, b, c, d;\n         \n        sin = gSineTable[(u8)sprite->sRot];\n        cos = gSineTable[(u8)(sprite->sRot + 64)];\n         \n        d = Q_8_8_TO_INT( cos * sprite->sScale);\n        c = Q_8_8_TO_INT(-sin * sprite->sScale);\n        b = Q_8_8_TO_INT( sin * sprite->sScale);\n        a = Q_8_8_TO_INT( cos * sprite->sScale);\n\n        SetOamMatrix(1, a, b, c, d);\n    }\n\n    switch (sprite->sState)\n    {\n    case 0:\n    default:\n        sprite->oam.affineMode = ST_OAM_AFFINE_DOUBLE;\n        sprite->oam.matrixNum = 1;\n        CalcCenterToCornerVec(sprite, SPRITE_SHAPE(64x32), SPRITE_SIZE(64x32), ST_OAM_AFFINE_DOUBLE);\n        sprite->invisible = FALSE;\n        sprite->sState = 1;\n        sprite->sScale = 128;\n        sprite->sRot = 0;\n        sprite->sPos = 0;\n        break;\n    case 1:\n        sprite->x2 = -Sin((u8)sprite->sPos, 140);\n        sprite->y2 = -Sin((u8)sprite->sPos, 120);\n        sprite->sScale += 7;\n        sprite->sPos += 3;\n        if (sprite->x + sprite->x2 <= -16)\n        {\n            sprite->oam.priority = 3;\n            sprite->sState++;\n            sprite->x = 20;\n            sprite->y = 40;\n            sprite->sScale = 512;\n            sprite->sRot = 0;\n            sprite->sPos = 16;\n        }\n        break;\n    case 2:\n        sprite->x2 = Sin((u8)sprite->sPos, 34);\n        sprite->y2 = -Cos((u8)sprite->sPos, 60);\n        sprite->sScale += 2;\n        if (sprite->sTimer % 5 == 0)\n            sprite->sPos++;\n        break;\n    }",
  "SpriteCB_GameFreakLogo": "switch(sprite->sState)\n    {\n    case 0:\n        if (gIntroFrameCounter == TIMER_LOGO_APPEAR)\n        {\n            sprite->invisible = FALSE;\n            sprite->sState++;\n        }\n        break;\n    case 1:\n        if (gIntroFrameCounter == TIMER_LOGO_DISAPPEAR)\n        {\n             \n            StartSpriteAffineAnim(sprite, 3);\n            sprite->sState++;\n        }\n        break;\n    case 2:\n        if (sprite->affineAnimEnded)\n            DestroySprite(sprite);\n        break;\n    }",
  "SpriteCB_GroudonRocks": "sprite->sTimer++;\n    if (sprite->sTimer % 2 == 0)\n        sprite->y2 ^= 3;\n\n    switch(sprite->sState)\n    {\n    case 0:\n         \n        sprite->sSpeed += sGroudonRockData[sprite->sRockId][2];\n        sprite->y -= (sprite->sSpeed & 0xFF00) >> 8;\n        sprite->sSpeed &= 0xFF;\n\n         \n        if (gTasks[sprite->sTaskId].tState > 7)\n            sprite->sState++;\n        break;\n    case 1:\n         \n        if (sprite->x < DISPLAY_WIDTH / 2)\n            sprite->x -= 2;\n        else\n            sprite->x += 2;\n\n        if (sprite->y < DISPLAY_HEIGHT / 2)\n            sprite->y -= 2;\n        else\n            sprite->y += 2;\n        break;\n    }",
  "SpriteCB_InputArrow": "const s16 x[] = {0, -4, -2, -1};\n\n    if (sprite->sDelay == 0 || --sprite->sDelay == 0)\n    {\n        sprite->sDelay = 8;\n        sprite->sXPosId = MOD(sprite->sXPosId + 1, ARRAY_COUNT(x));\n    }\n    sprite->x2 = x[sprite->sXPosId];",
  "SpriteCB_KyogreBubbles": "switch(sprite->sState)\n    {\n    case 0:\n        if (sprite->sDelay == 0)\n        {\n             \n            sprite->sSinIdx = (sprite->sSinIdx + 11) & 0xFF;\n            sprite->x2 = Sin(sprite->sSinIdx, 4);\n            sprite->sBaseY += 48;\n            sprite->y2 = -(sprite->sBaseY >> 8);\n            if (sprite->animEnded)\n                DestroySprite(sprite);\n        }\n        else if (--sprite->sDelay == 0)\n        {\n             \n            StartSpriteAnim(sprite, 0);\n            sprite->invisible = FALSE;\n        }\n\n         \n         \n        if (gTasks[sprite->sTaskId].tState > 11)\n            sprite->sState++;\n        break;\n    case 1:\n         \n        if (sprite->x < DISPLAY_WIDTH / 2)\n            sprite->x -= 3;\n        else\n            sprite->x += 3;\n\n        if (sprite->y < DISPLAY_HEIGHT / 2)\n            sprite->y -= 3;\n        else\n            sprite->y += 3;\n\n        if ((u16)(sprite->y - 20) > DISPLAY_HEIGHT - 20)\n            DestroySprite(sprite);\n        break;\n    }",
  "SpriteCB_Lightning": "if (sprite->animEnded)\n        sprite->invisible = TRUE;\n\n    switch(sprite->sState)\n    {\n    case 0:\n        sprite->sPalIdx = 0x1C2;\n        sprite->sState++;\n    case 1:\n        CpuCopy16(INTRO3_RAW_PTR(sprite->sPalIdx), &gPlttBufferFaded[BG_PLTT_ID(5) + 13], PLTT_SIZEOF(1));\n        sprite->sPalIdx += 2;\n        if (sprite->sPalIdx != 0x1CE)\n            break;\n        sprite->sPalIdx = 0x1CC;\n        sprite->sDelay = 4;\n        sprite->sState++;\n    case 2:\n        if (--sprite->sDelay == 0)\n        {\n            sprite->sDelay = 4;\n            CpuCopy16(INTRO3_RAW_PTR(sprite->sPalIdx), &gPlttBufferFaded[BG_PLTT_ID(5) + 13], PLTT_SIZEOF(1));\n            sprite->sPalIdx -= 2;\n            if (sprite->sPalIdx == 0x1C0)\n                DestroySprite(sprite);\n        }\n        break;\n    }",
  "SpriteCB_LogoLetter": "switch (sprite->sState)\n    {\n    case 0:\n        if (sprite->sTimer != 0)\n        {\n            sprite->sTimer--;\n        }\n        else\n        {\n             \n            sprite->invisible = FALSE;\n            StartSpriteAffineAnim(sprite, 1);\n            sprite->sState++;\n        }\n        break;\n    case 1:\n        if (gIntroFrameCounter == TIMER_LOGO_LETTERS_COLOR)\n        {\n             \n            sprite->sState++;\n            sprite->sTimer = COLOR_CHANGES;\n            sprite->sColorDelay = 2;\n        }\n        break;\n    case 2:\n         \n        if (sprite->sColorDelay == 0)\n        {\n            sprite->sColorDelay = 2;\n            if (sprite->sTimer != 0)\n            {\n                CpuCopy16(&gIntroGameFreakTextFade_Pal[sprite->sTimer],      &gPlttBufferFaded[OBJ_PLTT_ID(1) + 15], PLTT_SIZEOF(1));\n                CpuCopy16(&gIntroGameFreakTextFade_Pal[sprite->sTimer + 16], &gPlttBufferFaded[OBJ_PLTT_ID(1) + 4], PLTT_SIZEOF(1));\n                CpuCopy16(&gIntroGameFreakTextFade_Pal[sprite->sTimer + 32], &gPlttBufferFaded[OBJ_PLTT_ID(1) + 10], PLTT_SIZEOF(1));\n                sprite->sTimer--;\n            }\n            else\n            {\n                CpuCopy16(&gIntroGameFreakTextFade_Pal[sprite->sTimer],      &gPlttBufferFaded[OBJ_PLTT_ID(1) + 15], PLTT_SIZEOF(1));\n                CpuCopy16(&gIntroGameFreakTextFade_Pal[sprite->sTimer + 16], &gPlttBufferFaded[OBJ_PLTT_ID(1) + 4], PLTT_SIZEOF(1));\n                CpuCopy16(&gIntroGameFreakTextFade_Pal[sprite->sTimer + 32], &gPlttBufferFaded[OBJ_PLTT_ID(1) + 10], PLTT_SIZEOF(1));\n                sprite->sState++;\n            }\n        }\n        else\n        {\n            sprite->sColorDelay--;\n        }\n        break;\n    case 3:\n         \n        if (sprite->sColorDelay != 0)\n        {\n            sprite->sColorDelay--;\n        }\n        else\n        {\n            sprite->sColorDelay = 2;\n            if (sprite->sTimer <= COLOR_CHANGES)\n            {\n                CpuCopy16(&gIntroGameFreakTextFade_Pal[sprite->sTimer],      &gPlttBufferFaded[OBJ_PLTT_ID(1) + 15], PLTT_SIZEOF(1));\n                CpuCopy16(&gIntroGameFreakTextFade_Pal[sprite->sTimer + 16], &gPlttBufferFaded[OBJ_PLTT_ID(1) + 4], PLTT_SIZEOF(1));\n                CpuCopy16(&gIntroGameFreakTextFade_Pal[sprite->sTimer + 32], &gPlttBufferFaded[OBJ_PLTT_ID(1) + 10], PLTT_SIZEOF(1));\n                sprite->sTimer++;\n            }\n            else\n            {\n                sprite->sState++;\n            }\n        }\n        break;\n    case 4:\n        if (gIntroFrameCounter == TIMER_LOGO_DISAPPEAR)\n        {\n             \n            StartSpriteAffineAnim(sprite, 2);\n            sprite->oam.objMode = ST_OAM_OBJ_BLEND;\n            sprite->sState++;\n        }\n        break;\n    case 5:\n         \n        sprite->sLetterX += sGameFreakLettersMoveSpeed[sprite->sLetterId];\n        sprite->x2 = (sprite->sLetterX & 0xFF00) >> 8;\n        if (sprite->sLetterId < 4)\n        {\n             \n            s16 temp = sprite->x2;\n            sprite->x2 = -temp;\n        }\n        if (sprite->affineAnimEnded)\n            DestroySprite(sprite);\n        break;\n    }",
  "SpriteCB_Manectric": "switch (sprite->sState)\n    {\n    case 0:\n        if (gIntroFrameCounter == TIMER_MANECTRIC_ENTER)\n            sprite->sState++;\n        break;\n    case 1:\n        sprite->x -= 2;\n        if (gIntroFrameCounter != TIMER_MANECTRIC_RUN_CIRCULAR)\n            break;\n\n         \n        sprite->y -= 12;\n        sprite->sSinIdx = 0x80;\n        sprite->sCosIdx = 0;\n        sprite->sState++;\n         \n    case 2:\n        if (sprite->x + sprite->x2 <= -32)\n        {\n             \n            DestroySprite(sprite);\n        }\n        else\n        {\n             \n            if ((sprite->sSinIdx & 0xFF) < 64)\n            {\n                sprite->x2 = Sin((u8)sprite->sSinIdx, 16);\n            }\n            else\n            {\n                if ((sprite->sSinIdx & 0xFF) == 64)\n                    sprite->x -= 48;\n                sprite->x2 = Sin((u8)sprite->sSinIdx, 64);\n            }\n            sprite->sSinIdx++;\n            sprite->y2 = Cos((u8)sprite->sCosIdx, 12);\n            sprite->sCosIdx++;\n        }\n        break;\n    }",
  "SpriteCB_MovePlayerDownWhileShrinking": "u32 y;\n\n    y = (sprite->y << 16) + sprite->data[0] + 0xC000;\n    sprite->y = y >> 16;\n    sprite->data[0] = y;",
  "SpriteCB_MovingScenery": "s32 x;\n    s16 state = gIntroCredits_MovingSceneryState;\n\n    if (state != INTROCRED_SCENERY_FROZEN)\n    {\n        switch (state)\n        {\n        default:  \n            DestroySprite(sprite);\n            break;\n        case INTROCRED_SCENERY_NORMAL:\n            x = ((sprite->x << 16) | (u16)sprite->tXPos) + (u16)sprite->tXOffset;\n            sprite->x = x >> 16;\n            sprite->tXPos = x;\n            if (sprite->x > 255)\n                sprite->x = -32;\n            if (sprite->tHasVerticalMove)\n                sprite->y2 = -(gIntroCredits_MovingSceneryVBase + gIntroCredits_MovingSceneryVOffset);\n            else\n                sprite->y2 = -gIntroCredits_MovingSceneryVBase;\n            break;\n        }\n    }",
  "SpriteCB_Null": "",
  "SpriteCB_PageSwap": "while (sPageSwapSpriteFuncs[sprite->sState](sprite));",
  "SpriteCB_Player": "if (gIntroCredits_MovingSceneryState != INTROCRED_SCENERY_NORMAL)\n    {\n        DestroySprite(sprite);\n        return;\n    }\n\n    switch (sprite->sState)\n    {\n    case 0:\n        StartSpriteAnimIfDifferent(sprite, 0);\n        break;\n    case 1:\n        StartSpriteAnimIfDifferent(sprite, 1);\n        if (sprite->x > -32)\n            sprite->x--;\n        break;\n    case 2:\n        StartSpriteAnimIfDifferent(sprite, 2);\n        break;\n    case 3:\n        StartSpriteAnimIfDifferent(sprite, 3);\n        break;\n    case 4:\n        StartSpriteAnimIfDifferent(sprite, 0);\n        if (sprite->x > DISPLAY_WIDTH / 2)\n            sprite->x--;\n        break;\n    case 5:\n        StartSpriteAnimIfDifferent(sprite, 0);\n        if (sprite->x > -32)\n            sprite->x--;\n        break;\n    }",
  "SpriteCB_PlayerOnBicycle": "switch (sprite->sState)\n    {\n    case 0:\n         \n        StartSpriteAnimIfDifferent(sprite, 0);\n        sprite->x--;\n        break;\n    case 1:\n         \n        StartSpriteAnimIfDifferent(sprite, 0);\n        if (gIntroFrameCounter & 7)\n            return;\n        sprite->x++;\n        break;\n    case 2:\n         \n        if (sprite->x <= 120 || gIntroFrameCounter & 7)\n            sprite->x++;\n        break;\n    case 3:\n         \n        break;\n    case 4:\n         \n        if (sprite->x > -32)\n            sprite->x -= 2;\n        break;\n    }\n\n    if (gIntroFrameCounter & 7)\n        return;\n\n     \n    if (sprite->y2 != 0)\n    {\n         \n        sprite->y2 = 0;\n    }\n    else\n    {\n         \n        switch (Random() & 3)\n        {\n        case 0:\n            sprite->y2 = -1;\n            break;\n        case 1:\n            sprite->y2 = 1;\n            break;\n        case 2:\n        case 3:\n            sprite->y2 = 0;\n            break;\n        }\n    }",
  "SpriteCB_PokemonLogoShine": "if (sprite->x < DISPLAY_WIDTH + 32)\n    {\n         \n         \n        if (sprite->sMode != SHINE_MODE_SINGLE_NO_BG_COLOR)\n        {\n            u16 backgroundColor;\n\n            if (sprite->x < DISPLAY_WIDTH / 2)\n            {\n                 \n                if (sprite->sBgColor < 31)\n                    sprite->sBgColor++;\n                if (sprite->sBgColor < 31)\n                    sprite->sBgColor++;\n            }\n            else\n            {\n                 \n                if (sprite->sBgColor != 0)\n                    sprite->sBgColor--;\n                if (sprite->sBgColor != 0)\n                    sprite->sBgColor--;\n            }\n\n            backgroundColor = _RGB(sprite->sBgColor, sprite->sBgColor, sprite->sBgColor);\n\n             \n             \n            if (sprite->x == DISPLAY_WIDTH / 2 + (3 * SHINE_SPEED)\n             || sprite->x == DISPLAY_WIDTH / 2 + (4 * SHINE_SPEED)\n             || sprite->x == DISPLAY_WIDTH / 2 + (5 * SHINE_SPEED)\n             || sprite->x == DISPLAY_WIDTH / 2 + (6 * SHINE_SPEED))\n                gPlttBufferFaded[0] = RGB(24, 31, 12);\n            else\n                gPlttBufferFaded[0] = backgroundColor;\n        }\n\n        sprite->x += SHINE_SPEED;\n    }\n    else\n    {\n         \n        gPlttBufferFaded[0] = RGB_BLACK;\n        DestroySprite(sprite);\n    }",
  "SpriteCB_PokemonLogoShine_Fast": "if (sprite->x < DISPLAY_WIDTH + 32)\n        sprite->x += SHINE_SPEED * 2;\n    else\n        DestroySprite(sprite);",
  "SpriteCB_PressStartCopyrightBanner": "if (sprite->sAnimate == TRUE)\n    {\n         \n        if (++sprite->sTimer & 16)\n            sprite->invisible = FALSE;\n        else\n            sprite->invisible = TRUE;\n    }\n    else\n    {\n        sprite->invisible = FALSE;\n    }",
  "SpriteCB_RayquazaOrb": "u16 foo;\n    switch (sprite->sState)\n    {\n    case 0:\n    default:\n        sprite->invisible = FALSE;\n        sprite->oam.affineMode = ST_OAM_AFFINE_DOUBLE;\n        sprite->oam.matrixNum = 18;\n        CalcCenterToCornerVec(sprite, SPRITE_SHAPE(64x64), SPRITE_SIZE(64x64), ST_OAM_AFFINE_DOUBLE);\n        sprite->data[1] = 0;\n        sprite->sState = 1;\n         \n    case 1:\n        sprite->data[7]++;\n        if (sprite->data[7] & 1)\n        {\n            sprite->invisible = TRUE;\n        }\n        else\n        {\n            sprite->invisible = FALSE;\n            if (sprite->data[1] < 64)\n                sprite->data[1]++;\n        }\n        foo = 256 - gSineTable[(u8)sprite->data[1]] / 2;\n        SetOamMatrix(18, foo, 0, 0, foo);\n        break;\n    }",
  "SpriteCB_Rival": "if (gIntroCredits_MovingSceneryState != INTROCRED_SCENERY_NORMAL)\n    {\n        DestroySprite(sprite);\n        return;\n    }\n\n    switch (sprite->sState)\n    {\n    case 0:\n        sprite->y2 = 0;\n        StartSpriteAnimIfDifferent(sprite, 0);\n        break;\n    case 1:\n        if (sprite->x > 200)\n            StartSpriteAnimIfDifferent(sprite, 1);\n        else\n            StartSpriteAnimIfDifferent(sprite, 2);\n        if (sprite->x > -32)\n            sprite->x -= 2;\n        sprite->y2 = -gIntroCredits_MovingSceneryVOffset;\n        break;\n    case 2:\n        sprite->data[7]++;\n        StartSpriteAnimIfDifferent(sprite, 0);\n        if ((sprite->data[7] & 3) == 0)\n            sprite->x++;\n        break;\n    case 3:\n        StartSpriteAnimIfDifferent(sprite, 0);\n        if (sprite->x > -32)\n            sprite->x--;\n        break;\n    }",
  "SpriteCB_Sparkle": "if (++sprite->sTimer == 12)\n        DestroySprite(sprite);",
  "SpriteCB_Torchic": "switch (sprite->sState)\n    {\n    case 0:\n        if (gIntroFrameCounter == TIMER_TORCHIC_ENTER)\n        {\n            StartSpriteAnim(sprite, TORCHIC_ANIM_RUN);\n            sprite->sState++;\n        }\n        break;\n    case 1:\n        if (gIntroFrameCounter == TIMER_PLAYER_HOLD_POSITION)\n        {\n            StartSpriteAnim(sprite, TORCHIC_ANIM_WALK);\n            sprite->sState++;\n        }\n        else\n        {\n            sprite->sMoveTimer += 64;\n            if (sprite->sMoveTimer & 0xFF00)\n            {\n                sprite->x--;\n                sprite->sMoveTimer &= 0xFF;\n            }\n        }\n        break;\n    case 2:\n        if (gIntroFrameCounter != TIMER_TORCHIC_SPEED_UP)\n        {\n            sprite->sMoveTimer += 32;\n            if (sprite->sMoveTimer & 0xFF00)\n            {\n                sprite->x++;\n                sprite->sMoveTimer &= 0xFF;\n            }\n        }\n        else\n        {\n            StartSpriteAnim(sprite, TORCHIC_ANIM_RUN);\n            sprite->sState++;\n            sprite->sDelay = 80;\n        }\n        break;\n    case 3:\n        if (--sprite->sDelay)\n        {\n            sprite->sMoveTimer += 64;\n            if (sprite->sMoveTimer & 0xFF00)\n            {\n                sprite->x--;\n                sprite->sMoveTimer &= 0xFF;\n            }\n        }\n        else\n        {\n            StartSpriteAnim(sprite, TORCHIC_ANIM_TRIP);\n            sprite->sState++;\n        }\n        break;\n    case 4:\n        if (sprite->animEnded)\n            sprite->x += 4;\n\n        if (sprite->x > 336)\n        {\n            StartSpriteAnim(sprite, TORCHIC_ANIM_RUN);\n            sprite->sState++;\n        }\n        break;\n    case 5:\n        if (gIntroFrameCounter >= TIMER_TORCHIC_EXIT)\n            sprite->x -= 2;\n        break;\n    }",
  "SpriteCB_Underscore": "const s16 y[] = {2, 3, 2, 1};\n    u8 pos;\n\n    pos = GetTextEntryPosition();\n    if (pos != (u8)sprite->sId)\n    {\n        sprite->y2 = 0;\n        sprite->sYPosId = 0;\n        sprite->sDelay = 0;\n    }\n    else\n    {\n        sprite->y2 = y[sprite->sYPosId];\n        sprite->sDelay++;\n        if (sprite->sDelay > 8)\n        {\n            sprite->sYPosId = MOD(sprite->sYPosId + 1, ARRAY_COUNT(y));\n            sprite->sDelay = 0;\n        }\n    }",
  "SpriteCB_VersionBannerLeft": "if (gTasks[sprite->sParentTaskId].tSkipToNext)\n    {\n        sprite->oam.objMode = ST_OAM_OBJ_NORMAL;\n        sprite->y = VERSION_BANNER_Y_GOAL;\n    }\n    else\n    {\n        if (sprite->y != VERSION_BANNER_Y_GOAL)\n            sprite->y++;\n        if (sprite->sAlphaBlendIdx != 0)\n            sprite->sAlphaBlendIdx--;\n        SetGpuReg(REG_OFFSET_BLDALPHA, gTitleScreenAlphaBlend[sprite->sAlphaBlendIdx]);\n    }",
  "SpriteCB_VersionBannerRight": "if (gTasks[sprite->sParentTaskId].tSkipToNext)\n    {\n        sprite->oam.objMode = ST_OAM_OBJ_NORMAL;\n        sprite->y = VERSION_BANNER_Y_GOAL;\n    }\n    else\n    {\n        if (sprite->y != VERSION_BANNER_Y_GOAL)\n            sprite->y++;\n    }",
  "SpriteCB_Volbeat": "sprite->sCosYIdx += 4;\n    switch (sprite->sState)\n    {\n    case VOLBEAT_WAIT_ENTER:\n        if (++sprite->sStateDelay < 180)\n            break;\n        sprite->sState++;\n         \n    case VOLBEAT_ENTER:\n        sprite->x -= 4;\n        if (sprite->x == 60)\n        {\n            sprite->sState = VOLBEAT_WAIT_STATE;\n            sprite->sStateDelay = 20;\n            sprite->sNextState = VOLBEAT_ZIP_BACKWARD;\n        }\n        break;\n    case VOLBEAT_ZIP_BACKWARD:\n        sprite->x += 8;\n        sprite->y -= 2;\n        if (sprite->x == 124)\n        {\n            sprite->sState = VOLBEAT_WAIT_STATE;\n            sprite->sStateDelay = 20;\n            sprite->sNextState = VOLBEAT_ZIP_DOWN;\n        }\n        break;\n    case VOLBEAT_ZIP_DOWN:\n        sprite->y += 4;\n        if (sprite->y == 80)\n        {\n            sprite->sState = VOLBEAT_WAIT_STATE;\n            sprite->sStateDelay = 10;\n            sprite->sNextState = VOLBEAT_ZIP_FORWARD;\n        }\n        break;\n    case VOLBEAT_ZIP_FORWARD:\n        sprite->x -= 8;\n        sprite->y -= 2;\n        if (sprite->x == 60)\n        {\n            sprite->sState = VOLBEAT_WAIT_STATE;\n            sprite->sStateDelay = 10;\n            sprite->sNextState = VOLBEAT_INIT_FIGURE_8;\n        }\n        break;\n    case VOLBEAT_INIT_FIGURE_8:\n        sprite->x += 60;\n        sprite->sSinXIdx = 0xC0;\n        sprite->sSinYIdx = 0x80;\n        sprite->sFig8Loops = 3;\n        sprite->sState++;\n         \n    case VOLBEAT_FIGURE_8:\n        sprite->x2 = Sin((u8)sprite->sSinXIdx, 0x3C);\n        sprite->y2 = Sin((u8)sprite->sSinYIdx, 0x14);\n        sprite->sSinXIdx += 2;\n        sprite->sSinYIdx += 4;\n        if ((sprite->sSinXIdx & 0xFF) == 64)\n        {\n            sprite->hFlip = FALSE;\n            if (--sprite->sFig8Loops == 0)\n            {\n                sprite->x += sprite->x2;\n                sprite->x2 = 0;\n                sprite->sState++;\n            }\n        }\n        break;\n    case VOLBEAT_EXIT:\n        sprite->x -= 2;\n        sprite->y2 = Sin((u8)sprite->sSinYIdx, 0x14);\n        sprite->sSinYIdx += 4;\n        if (sprite->x < -16)\n            DestroySprite(sprite);\n        break;\n    case VOLBEAT_WAIT_STATE:\n         \n        sprite->y2 = Cos((u8)sprite->sCosYIdx, 2);\n        if (!--sprite->sStateDelay)\n            sprite->sState = sprite->sNextState;\n        break;\n    }",
  "SpriteCB_WaterDrop": "if (sprite->sState != 0)\n        sprite->callback = SpriteCB_WaterDrop_Slide;",
  "SpriteCB_WaterDropHalf": "if (gSprites[sprite->data[7]].data[7] != 0)\n    {\n        sprite->invisible = TRUE;\n        sprite->x += sprite->x2;\n        sprite->y += sprite->y2;\n        StartSpriteAnim(sprite, DROP_ANIM_RIPPLE);\n        sprite->data[2] = 1024;\n        sprite->data[3] = 8 * (sprite->data[1] & 3);\n        sprite->callback = SpriteCB_WaterDrop_Ripple;\n        sprite->oam.shape = SPRITE_SHAPE(64x32);\n        sprite->oam.size = SPRITE_SIZE(64x32);\n        CalcCenterToCornerVec(sprite, SPRITE_SHAPE(64x32), SPRITE_SIZE(64x32), ST_OAM_AFFINE_ERASE);\n    }\n    else\n    {\n        sprite->x2 = gSprites[sprite->data[7]].x2;\n        sprite->y2 = gSprites[sprite->data[7]].y2;\n        sprite->x = gSprites[sprite->data[7]].x;\n        sprite->y = gSprites[sprite->data[7]].y;\n    }",
  "SpriteCB_WaterDropShort": "if (sprite->y < sprite->data[5])\n    {\n        sprite->y += 4;\n    }\n    else\n    {\n        sprite->data[7] = 1;\n        sprite->invisible = TRUE;\n        sprite->x += sprite->x2;\n        sprite->y += sprite->y2;\n        StartSpriteAnim(sprite, DROP_ANIM_RIPPLE);\n        sprite->data[2] = 1024;\n        sprite->data[3] = 8 * (sprite->data[1] & 3);\n        sprite->callback = SpriteCB_WaterDrop_Ripple;\n        sprite->oam.shape = SPRITE_SHAPE(64x32);\n        sprite->oam.size = SPRITE_SIZE(64x32);\n        CalcCenterToCornerVec(sprite, SPRITE_SHAPE(64x32), SPRITE_SIZE(64x32), ST_OAM_AFFINE_ERASE);\n    }",
  "SpriteCB_WaterDrop_DangleFromLeaf": "if (sprite->data[0] != 2)\n    {\n        s16 r2;\n\n        sprite->data[4] += 8;\n        r2 = gSineTable[(u8)sprite->data[4]] / 16 + 64;\n        sprite->x2 = gSineTable[(u8)(r2 + 64)] / 64;\n        sprite->y2 = gSineTable[(u8)r2] / 64;\n    }\n    else\n    {\n        sprite->callback = SpriteCB_WaterDrop_Fall;\n    }",
  "SpriteCB_WaterDrop_Fall": "if (sprite->y < sprite->data[5])\n    {\n        sprite->y += 4;\n    }\n    else\n    {\n        sprite->data[7] = 1;\n        sprite->invisible = TRUE;\n        sprite->x += sprite->x2;\n        sprite->y += sprite->y2;\n        StartSpriteAnim(sprite, DROP_ANIM_RIPPLE);\n        sprite->data[2] = 1024;\n        sprite->data[3] = 8 * (sprite->data[1] & 3);\n        sprite->callback = SpriteCB_WaterDrop_Ripple;\n        sprite->oam.shape = SPRITE_SHAPE(64x32);\n        sprite->oam.size = SPRITE_SIZE(64x32);\n        CalcCenterToCornerVec(sprite, SPRITE_SHAPE(64x32), SPRITE_SIZE(64x32), ST_OAM_AFFINE_ERASE);\n    }",
  "SpriteCB_WaterDrop_ReachLeafEnd": "SetOamMatrix(sprite->data[1], sprite->data[6] + 64, 0, 0, sprite->data[6] + 64);\n    SetOamMatrix(sprite->data[1] + 1, sprite->data[6] + 64, 0, 0, sprite->data[6] + 64);\n    SetOamMatrix(sprite->data[1] + 2, sprite->data[6] + 64, 0, 0, sprite->data[6] + 64);\n    if (sprite->data[4] != MAX_SPRITES)\n    {\n        u16 sinIdx;\n        sprite->data[4] -= 8;\n        sinIdx = sprite->data[4];\n        sprite->x2 = gSineTable[(u8)(sinIdx + 64)] / 64;\n        sprite->y2 = gSineTable[(u8)sinIdx] / 64;\n    }\n    else\n    {\n        sprite->data[4] = 0;\n        sprite->callback = SpriteCB_WaterDrop_DangleFromLeaf;\n    }",
  "SpriteCB_WaterDrop_Ripple": "u8 palNum;\n\n    if (sprite->data[2] >= 192)\n    {\n        if (sprite->data[3] != 0)\n        {\n            sprite->data[3]--;\n        }\n        else\n        {\n            sprite->invisible = FALSE;\n            SetOamMatrix(sprite->data[1], sprite->data[2], 0, 0, sprite->data[2]);\n            sprite->data[2] = (sprite->data[2] * 95) / 100;\n            palNum = (sprite->data[2] - 192) / 128 + 9;\n            if (palNum > 15)\n                palNum = 15;\n            sprite->oam.paletteNum = palNum;\n        }\n    }\n    else\n    {\n        DestroySprite(sprite);\n    }",
  "SpriteCB_WaterDrop_Slide": "if (sprite->x <= 116)\n    {\n        sprite->y += sprite->y2;\n        sprite->y2 = 0;\n        sprite->x += 4;\n        sprite->x2 = -4;\n        sprite->data[4] = 128;\n        sprite->callback = SpriteCB_WaterDrop_ReachLeafEnd;\n    }\n    else\n    {\n        u16 data2;\n        u16 data3;\n        u16 data4;\n        s16 sin1;\n        s16 sin2;\n        s16 sin3;\n        s16 sin4;\n        s16 var1;\n        s16 var2;\n        s16 var3;\n        s16 var4;\n        s16 temp;\n\n        data4 = sprite->data[4];\n        sin1 = gSineTable[(u8)data4];\n        sin2 = gSineTable[(u8)(data4 + 64)];\n        sprite->data[4] += 2;\n        sprite->y2 = sin1 / 32;\n        sprite->x--;\n        if (sprite->x & 1)\n            sprite->y++;\n        temp = -sin2 / 16;\n        data2 = sprite->data[2];\n        data3 = sprite->data[3];\n        sin3 = gSineTable[(u8)(temp - 16)];\n        sin4 = gSineTable[(u8)(temp + 48)];\n        var1 = sin4 * data2 / 256;\n        var2 = -sin3 * data3 / 256;\n        var3 = sin3 * data2 / 256;\n        var4 = sin4 * data3 / 256;\n        SetOamMatrix(sprite->data[1], data2, 0, 0, data3);\n        SetOamMatrix(sprite->data[1] + 1, var1, var3, var2, var4);\n        SetOamMatrix(sprite->data[1] + 2, var1, var3, var2 * 2, var4 * 2);\n    }",
} as const;

export const SPRITE_HELPERS = {
  "CreateBackOkSprites": {"params":"void","bodyC":"u8 spriteId;\n\n    spriteId = CreateSprite(&sSpriteTemplate_BackButton, 204, 116, 0);\n    SetSubspriteTables(&gSprites[spriteId], sSubspriteTable_Button);\n    gSprites[spriteId].invisible = TRUE;\n\n    spriteId = CreateSprite(&sSpriteTemplate_OkButton, 204, 140, 0);\n    SetSubspriteTables(&gSprites[spriteId], sSubspriteTable_Button);\n    gSprites[spriteId].invisible = TRUE;"},
  "CreateBicycleBgAnimationTask": {"params":"u8 mode, u16 bg1Speed, u16 bg2Speed, u16 bg3Speed","bodyC":"u8 taskId = CreateTask(Task_BicycleBgAnimation, 0);\n\n    gTasks[taskId].tMode = mode;\n    gTasks[taskId].tBg1Speed = bg1Speed;\n    gTasks[taskId].tBg1PosHi = 0;\n    gTasks[taskId].tBg1PosLo = 0;\n    gTasks[taskId].tBg2Speed = bg2Speed;\n    gTasks[taskId].tBg2PosHi = 0;\n    gTasks[taskId].tBg2PosLo = 0;\n    gTasks[taskId].tBg3Speed = bg3Speed;\n    gTasks[taskId].tBg3PosHi = 8;\n    gTasks[taskId].tBg3PosLo = 0;\n    Task_BicycleBgAnimation(taskId);\n    return taskId;"},
  "CreateCloudSprites": {"params":"void","bodyC":"CreateMovingScenerySprites(FALSE, sSpriteMetadata_Clouds, sAnims_Clouds, 9);"},
  "CreateCopyrightBanner": {"params":"s16 x, s16 y","bodyC":"u8 i;\n    u8 spriteId;\n\n    x -= 64;\n    for (i = 0; i < NUM_COPYRIGHT_FRAMES; i++, x += 32)\n    {\n        spriteId = CreateSprite(&sStartCopyrightBannerSpriteTemplate, x, y, 0);\n        StartSpriteAnim(&gSprites[spriteId], i + NUM_PRESS_START_FRAMES);\n    }"},
  "CreateCreditsMonSprite": {"params":"u16 nationalDexNum, s16 x, s16 y, u16 position","bodyC":"u8 monSpriteId;\n    u8 bgSpriteId;\n\n    monSpriteId = CreateMonSpriteFromNationalDexNumber(nationalDexNum, x, y, position);\n    gSprites[monSpriteId].oam.priority = 1;\n    gSprites[monSpriteId].sPosition = position + 1;\n    gSprites[monSpriteId].invisible = TRUE;\n    gSprites[monSpriteId].callback = SpriteCB_CreditsMon;\n    gSprites[monSpriteId].sSpriteId = monSpriteId;\n\n    bgSpriteId = CreateSprite(&sSpriteTemplate_CreditsMonBg, gSprites[monSpriteId].x, gSprites[monSpriteId].y, 1);\n    gSprites[bgSpriteId].sMonSpriteId = monSpriteId;\n\n    StartSpriteAnimIfDifferent(&gSprites[bgSpriteId], position);\n\n    return monSpriteId;"},
  "CreateCursorSprite": {"params":"void","bodyC":"sNamingScreen->cursorSpriteId = CreateSprite(&sSpriteTemplate_Cursor, 38, 88, 1);\n    SetCursorInvisibility(TRUE);\n    gSprites[sNamingScreen->cursorSpriteId].oam.priority = 1;\n    gSprites[sNamingScreen->cursorSpriteId].oam.objMode = ST_OAM_OBJ_BLEND;\n    gSprites[sNamingScreen->cursorSpriteId].sColorIncr = 1;  \n    gSprites[sNamingScreen->cursorSpriteId].sColorIncr = 2;\n    SetCursorPos(0, 0);"},
  "CreateGameFreakLogoSprites": {"params":"s16 x, s16 y, s16 unused","bodyC":"u16 i;\n    u8 spriteId;\n\n     \n    for (i = 0; i < NUM_GF_LETTERS; i++)\n    {\n        spriteId = CreateSprite(&sSpriteTemplate_GameFreakLetter, sGameFreakLetterData[i][1] + x, y - 4, 0);\n        gSprites[spriteId].sState = 0;\n        gSprites[spriteId].sTimer = sGameFreakLetterStartDelays[i];\n        gSprites[spriteId].sLetterId = i;\n        gSprites[spriteId].invisible = TRUE;\n        gSprites[spriteId].oam.matrixNum = i + 12;\n        StartSpriteAnim(&gSprites[spriteId], sGameFreakLetterData[i][0]);\n        StartSpriteAffineAnim(&gSprites[spriteId], 0);\n    }\n\n     \n    spriteId = CreateSprite(&sSpriteTemplate_GameFreakLogo, 120, y - 6, 0);\n    gSprites[spriteId].sState = 0;\n    gSprites[spriteId].invisible = TRUE;\n    gSprites[spriteId].oam.matrixNum = i + 12;\n    StartSpriteAffineAnim(&gSprites[spriteId], 1);\n\n    return spriteId;"},
  "CreateGroudonRockSprites": {"params":"u8 taskId","bodyC":"int i;\n    u8 spriteId;\n\n    for (i = 0; i < (int)ARRAY_COUNT(sGroudonRockData); i++)\n    {\n        spriteId = CreateSprite(&gAncientPowerRockSpriteTemplate, sGroudonRockData[i][0], DISPLAY_HEIGHT, i);\n        gSprites[spriteId].callback = SpriteCB_GroudonRocks;\n        gSprites[spriteId].oam.priority = 0;\n        gSprites[spriteId].sRockId = i;\n        gSprites[spriteId].sTaskId = taskId;\n        StartSpriteAnim(&gSprites[spriteId], sGroudonRockData[i][1]);\n    }"},
  "CreateHouseSprites": {"params":"void","bodyC":"CreateMovingScenerySprites(TRUE, sSpriteMetadata_HouseSilhouette, sAnims_HouseSilhouette, 6);"},
  "CreateIntroBrendanSprite": {"params":"s16 x, s16 y","bodyC":"u8 playerSpriteId = CreateSprite(&sSpriteTemplate_Brendan, x, y, 2);\n    u8 bicycleSpriteId = CreateSprite(&sSpriteTemplate_BrendanBicycle, x, y + 8, 3);\n    gSprites[bicycleSpriteId].sPlayerSpriteId = playerSpriteId;\n    return playerSpriteId;"},
  "CreateIntroFlygonSprite": {"params":"s16 x, s16 y","bodyC":"u8 leftSpriteId = CreateSprite(&sSpriteTemplate_FlygonLatias, x - 32, y, 5);\n    u8 rightSpriteId = CreateSprite(&sSpriteTemplate_FlygonLatias, x + 32, y, 6);\n    gSprites[rightSpriteId].sLeftSpriteId = leftSpriteId;\n    StartSpriteAnim(&gSprites[rightSpriteId], 1);\n    gSprites[rightSpriteId].callback = &SpriteCB_FlygonRightHalf;\n    return leftSpriteId;"},
  "CreateIntroMaySprite": {"params":"s16 x, s16 y","bodyC":"u8 playerSpriteId = CreateSprite(&sSpriteTemplate_May, x, y, 2);\n    u8 bicycleSpriteId = CreateSprite(&sSpriteTemplate_MayBicycle, x, y + 8, 3);\n    gSprites[bicycleSpriteId].sPlayerSpriteId = playerSpriteId;\n    return playerSpriteId;"},
  "CreateKyogreBubbleSprites_Body": {"params":"u8 taskId","bodyC":"int i;\n    u8 spriteId;\n\n    for (i = 0; i < NUM_BUBBLES_IN_SET; i++)\n    {\n        spriteId = CreateSprite(&sSpriteTemplate_Bubbles,\n                                sKyogreBubbleData[i][0],\n                                sKyogreBubbleData[i][1],\n                                i);\n        gSprites[spriteId].invisible = TRUE;\n        gSprites[spriteId].sTaskId = taskId;\n        gSprites[spriteId].sDelay = sKyogreBubbleData[i][2];\n        gSprites[spriteId].sUnk = 64;\n    }"},
  "CreateKyogreBubbleSprites_Fins": {"params":"void","bodyC":"int i;\n    u8 spriteId;\n\n    for (i = 0; i < NUM_BUBBLES_IN_SET; i++)\n    {\n        spriteId = CreateSprite(&sSpriteTemplate_Bubbles,\n                                sKyogreBubbleData[i + NUM_BUBBLES_IN_SET][0],\n                                sKyogreBubbleData[i + NUM_BUBBLES_IN_SET][1],\n                                i);\n        gSprites[spriteId].invisible = TRUE;\n#ifdef BUGFIX\n        gSprites[spriteId].sDelay = sKyogreBubbleData[i + NUM_BUBBLES_IN_SET][2];\n#else\n        gSprites[spriteId].sDelay = sKyogreBubbleData[i][2];  \n#endif\n        gSprites[spriteId].sUnk = 64;\n    }"},
  "CreateMovingScenerySprites": {"params":"bool8 hasVerticalMove, const struct IntroCreditsSpriteMetadata *metadata, const union AnimCmd *const *anims, u8 numSprites","bodyC":"u8 i;\n\n    for(i = 0; i < numSprites; i++)\n    {\n        u8 sprite = CreateSprite(&sSpriteTemplate_MovingScenery, metadata[i].x, metadata[i].y, metadata[i].subpriority);\n        CalcCenterToCornerVec(&gSprites[sprite], metadata[i].shape, metadata[i].size, ST_OAM_AFFINE_OFF);\n        gSprites[sprite].oam.priority = 3;\n        gSprites[sprite].oam.shape = metadata[i].shape;\n        gSprites[sprite].oam.size = metadata[i].size;\n        gSprites[sprite].oam.paletteNum = 0;\n        gSprites[sprite].anims = anims;\n        StartSpriteAnim(&gSprites[sprite], metadata[i].animNum);\n        gSprites[sprite].tHasVerticalMove = hasVerticalMove;\n        gSprites[sprite].tXOffset = metadata[i].xOff;\n        gSprites[sprite].tXPos = 0;\n    }"},
  "CreatePageSwapButtonSprites": {"params":"void","bodyC":"u8 frameSpriteId;\n    u8 textSpriteId;\n    u8 buttonSpriteId;\n\n    frameSpriteId = CreateSprite(&sSpriteTemplate_PageSwapFrame, 204, 88, 0);\n    sNamingScreen->swapBtnFrameSpriteId = frameSpriteId;\n    SetSubspriteTables(&gSprites[frameSpriteId], sSubspriteTable_PageSwapFrame);\n    gSprites[frameSpriteId].invisible = TRUE;\n\n    textSpriteId = CreateSprite(&sSpriteTemplate_PageSwapText, 204, 84, 1);\n    gSprites[frameSpriteId].sTextSpriteId = textSpriteId;\n    SetSubspriteTables(&gSprites[textSpriteId], sSubspriteTable_PageSwapText);\n    gSprites[textSpriteId].invisible = TRUE;\n\n    buttonSpriteId = CreateSprite(&sSpriteTemplate_PageSwapButton, 204, 83, 2);\n    gSprites[buttonSpriteId].oam.priority = 1;\n    gSprites[frameSpriteId].sButtonSpriteId = buttonSpriteId;\n    gSprites[buttonSpriteId].invisible = TRUE;"},
  "CreatePressStartBanner": {"params":"s16 x, s16 y","bodyC":"u8 i;\n    u8 spriteId;\n\n    x -= 64;\n    for (i = 0; i < NUM_PRESS_START_FRAMES; i++, x += 32)\n    {\n        spriteId = CreateSprite(&sStartCopyrightBannerSpriteTemplate, x, y, 0);\n        StartSpriteAnim(&gSprites[spriteId], i);\n        gSprites[spriteId].sAnimate = TRUE;\n    }"},
  "CreateSprites": {"params":"void","bodyC":"CreateCursorSprite();\n    CreatePageSwapButtonSprites();\n    CreateBackOkSprites();\n    CreateTextEntrySprites();\n    CreateInputTargetIcon();"},
  "CreateSwapLineSprites": {"params":"u8 *spriteIds, u8 count","bodyC":"u8 i;\n\n    for (i = 0; i < count; i++)\n    {\n        spriteIds[i] = CreateSprite(&sSpriteTemplate_SwapLine, i * 16, 0, 0);\n        if (i != 0)\n            StartSpriteAnim(&gSprites[spriteIds[i]], 1);\n\n        gSprites[spriteIds[i]].invisible = TRUE;\n    }"},
  "CreateTextEntrySprites": {"params":"void","bodyC":"u8 spriteId;\n    s16 xPos;\n    u8 i;\n\n    xPos = sNamingScreen->inputCharBaseXPos - 5;\n    spriteId = CreateSprite(&sSpriteTemplate_InputArrow, xPos, 56, 0);\n    gSprites[spriteId].oam.priority = 3;\n    gSprites[spriteId].invisible = TRUE;\n    xPos = sNamingScreen->inputCharBaseXPos;\n    for (i = 0; i < sNamingScreen->template->maxChars; i++, xPos += 8)\n    {\n        spriteId = CreateSprite(&sSpriteTemplate_Underscore, xPos + 3, 60, 0);\n        gSprites[spriteId].oam.priority = 3;\n        gSprites[spriteId].data[0] = i;\n        gSprites[spriteId].invisible = TRUE;\n    }"},
  "CreateTreeSprites": {"params":"void","bodyC":"CreateMovingScenerySprites(TRUE, sSpriteMetadata_Trees, sAnims_Trees, 12);"},
  "CreateWaterDrop": {"params":"s16 x, s16 y, u16 c, u16 d, u16 e, u8 fallImmediately","bodyC":"u8 spriteId;\n    u8 oldSpriteId;\n\n     \n    spriteId = CreateSprite(&sSpriteTemplate_WaterDrop, x, y, 1);\n    gSprites[spriteId].data[0] = 0;\n    gSprites[spriteId].data[7] = 0;\n    gSprites[spriteId].data[1] = d;\n    gSprites[spriteId].data[2] = c;\n    gSprites[spriteId].data[3] = c;\n    gSprites[spriteId].data[5] = e;\n    gSprites[spriteId].data[6] = c;\n    gSprites[spriteId].oam.affineMode = ST_OAM_AFFINE_DOUBLE;\n    gSprites[spriteId].oam.matrixNum = d;\n    CalcCenterToCornerVec(&gSprites[spriteId], SPRITE_SHAPE(32x32), SPRITE_SIZE(32x32), ST_OAM_AFFINE_ERASE);\n    StartSpriteAnim(&gSprites[spriteId], DROP_ANIM_REFLECTION);\n    if (!fallImmediately)\n        gSprites[spriteId].callback = SpriteCB_WaterDrop;  \n    else\n        gSprites[spriteId].callback = SpriteCB_WaterDropShort;  \n    oldSpriteId = spriteId;\n\n     \n     \n    spriteId = CreateSprite(&sSpriteTemplate_WaterDrop, x, y, 1);\n    gSprites[spriteId].data[7] = oldSpriteId;\n    gSprites[spriteId].data[1] = d + 1;\n    gSprites[spriteId].oam.affineMode = ST_OAM_AFFINE_DOUBLE;\n    gSprites[spriteId].oam.matrixNum = d + 1;\n    CalcCenterToCornerVec(&gSprites[spriteId], SPRITE_SHAPE(32x32), SPRITE_SIZE(32x32), ST_OAM_AFFINE_ERASE);\n    gSprites[spriteId].callback = SpriteCB_WaterDropHalf;\n\n     \n    spriteId = CreateSprite(&sSpriteTemplate_WaterDrop, x, y, 1);\n    gSprites[spriteId].data[7] = oldSpriteId;\n    gSprites[spriteId].data[1] = d + 2;\n    StartSpriteAnim(&gSprites[spriteId], DROP_ANIM_LOWER_HALF);\n    gSprites[spriteId].oam.affineMode = ST_OAM_AFFINE_DOUBLE;\n    gSprites[spriteId].oam.matrixNum = d + 2;\n    CalcCenterToCornerVec(&gSprites[spriteId], SPRITE_SHAPE(32x32), SPRITE_SIZE(32x32), ST_OAM_AFFINE_ERASE);\n    gSprites[spriteId].callback = SpriteCB_WaterDropHalf;\n\n    SetOamMatrix(d, c + 32, 0, 0, c + 32);\n    SetOamMatrix(d + 1, c + 32, 0, 0, c + 32);\n    SetOamMatrix(d + 2, c + 32, 0, 0, 2 * (c + 32));\n\n    return oldSpriteId;"},
} as const;

